import { createHarness } from "@strands-agents/harness";

const agent = await createHarness({ model: "anthropic/claude-opus-5" });
await agent("Research the top three vector databases, compare pricing 
and limits, and write it up in comparison.md");

import { bindings, defineConfig } from "cf/config";

export default defineConfig(({ mode }) => ({
  worker: {
    name: "example-worker",
    env: {
      API_URL: bindings.text(
        mode === "production"
          ? "https://example.com"
          : "https://staging.example.com",
      ),
    },
  },
}));
